mapper.select:
SELECT r.character_id AS character_id, t.id, t.name, t.color, t.sort_order, 0 AS character_count FROM character_tag_relation r INNER JOIN character_tag t ON t.id = r.tag_id WHERE t.is_deleted = 0 AND r.character_id IN
#{characterId}
ORDER BY r.character_id ASC, t.sort_order ASC, t.id ASC
